// === Tab: mySketch ===
let epiColors, S, MAR;

function setup() {
	createCanvas(windowWidth, windowHeight);
	S = ~~(max(width, height) / 20);
	MAR = S;

	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors();

	background(232);
	loop();
}

function draw() {
	let currAngle = random(TAU), deltaAngle = random(-1, 1) 
	for (let y = MAR; y < height-MAR; y += S*0.75) {
		drawSinLine(y, S, currAngle += deltaAngle, random(0.05, 0.2)*deltaAngle);
	}
	// noLoop() removed for animation
}

function drawSinLine(y, sze, ang = 0, da = 0.1) {
	const clr = epiColors.getColor(random(epiColors.palette), 48); // alpha optional
	noStroke();
	fill(clr);
	for (let x = MAR; x < width-MAR; x += 4) {
		const f = (sin(ang) + 1) / 2;
		const d = sze * map(f, 0, 1, 0.2, 1);
		circle(x, y, d);
		ang += da;
	}
}

function mousePressed() {
	if (mouseButton != RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0.1*width) setup();
}
